{
  "headline": "FDA's records trace our supply to a plant classified OAI 257 days before the posting",
  "headline_cites": ["E12", "E10", "D3"],
  "sentences": [
    {
      "text": "Atracurium besylate is not on FDA's drug shortage list as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "The product used at both Corvale sites carries NDC 55150021710 and labeler AuroMedics Pharma LLC.",
      "cites": ["E1", "E2"]
    },
    {
      "text": "That NDC's SPL set ID f7b6a720 names Eugia Pharma Specialities Limited (FEI 3008461619) as the registered manufacturing plant.",
      "cites": ["E12"]
    },
    {
      "text": "FDA inspected that plant on 2026-02-06 and classified it OAI; the classification was posted on 2026-09-21.",
      "cites": ["E10"]
    },
    {
      "text": "The OAI posting occurred 257 days after the inspection end date.",
      "cites": ["E10"]
    },
    {
      "text": "A Warning Letter was issued to the same plant on 2024-08-15 following an earlier OAI inspection.",
      "cites": ["E8", "E11"]
    },
    {
      "text": "The recommended action is to transfer 20 vials of 100 mg/10 mL from Corvale General to Corvale East, which would give Corvale East 14 days on hand while Corvale General retains 20 days.",
      "cites": ["D4"]
    }
  ]
}
